"""Finish two records where official sources now expose every decision field."""
from __future__ import annotations
import json
from pathlib import Path
from typing import Any
ROOT=Path(__file__).resolve().parents[1]; CHECKED="2026-07-15"
def bi(en:str,tr:str)->dict[str,str]: return {"en":en,"tr":tr}
def src(u:str,t:str,k:str,f:list[str],en:str,tr:str,c:str="high")->dict[str,Any]: return {"url":u,"title":t,"source_type":k,"access_status":"ok","last_checked":CHECKED,"relevant_fields":f,"confidence":c,"notes":bi(en,tr)}
def load(n:str):
 p=ROOT/"data_base"/n; raw=p.read_text(encoding="utf8"); return p,raw,json.loads(raw)
def rows(d): return d if isinstance(d,list) else d.get("programs",d.get("universities",[]))
def get(d,i): return next(x for x in rows(d) if x.get("id")==i)
def save(p,raw,d):
 nl="\r\n" if "\r\n" in raw else "\n";p.write_text(json.dumps(d,ensure_ascii=False,indent=2).replace("\n",nl)+nl,encoding="utf8")
def add(p,x): p["source_log"]=[q for q in p.get("source_log",[]) if not(isinstance(q,dict) and q.get("url")==x["url"] and q.get("source_type")==x["source_type"])]+[x]

