 r["cost_profile"].update({"tuition_chf_per_semester":2190,"tuition_chf_per_year_min":4380,"tuition_chf_per_year_max":4380,"tuition_basis":"ETH fee group 2 published semester fee; fee group must be confirmed","verification_notes":bi("ETH's published higher fee for fee group 2 is CHF 2,190 per semester. Eligibility is based on ETH fee-group rules, not nationality alone, so this card does not assume every non-EU applicant has this status.","ETH'nin fee group 2 icin yayimladigi yuksek ucret donem basina 2.190 CHF'dir. Uygunluk sadece uyruga degil ETH fee-group kurallarina baglidir; kart her AB disi aday icin bunu varsaymaz."),"living_cost_chf_per_year":25200})
 r["scholarship_profile"].update({"available_types":["ETH Excellence Scholarship & Opportunity Programme (ESOP)"],"regional_scholarship_available":True,"regional_scholarship_name":"ESOP","non_eu_eligible":True,"scholarship_deadline":"2026-11-30 11:59 CET (HS27 ESOP/international application window)","scholarship_application_url":esop,"funding_amount_chf_per_semester":12000,"tuition_waivers":["ESOP tuition-fee waiver"],"funding_notes":bi("ESOP for the 2027/28 Master start is open 1-30 November 2026. It provides CHF 12,000 per semester plus a tuition-fee waiver for the regular Master duration; applicants need top-10% Bachelor performance and apply with the Master application.","2027/28 Master baslangici icin ESOP 1-30 Kasim 2026'da aciktir. Normal Master suresi icin donem basina 12.000 CHF ve ogrenim ucreti muafiyeti sunar; adaylarin lisans derecesinde ilk %10'da olmasi ve Master basvurusuyla basvurmasi gerekir.")})
 r["living_profile"].update({"housing_budget_chf_per_year":11300,"official_student_total_budget_chf_per_year":25200,"living_risk":"high","housing_difficulty":"high","housing_notes":bi("ETH Financial Aid's 2025 Canton Zurich planning table gives CHF 11,300/year average room rent and CHF 25,200/year individual living costs for fee groups 1 and 2. It is a current planning budget, not a room offer.","ETH Financial Aid'in 2025 Kanton Zurich planlama tablosu, fee group 1 ve 2 icin yillik ortalama oda kirasi 11.300 CHF ve bireysel yasam gideri 25.200 CHF verir. Bu oda teklifi degil guncel planlama butcesidir.")})
 r["curriculum_profile"].update({"structure":bi("Tutor-driven individual Learning Agreement across six categories.","Alti kategoriye yayilan, tutor yonlendirmeli bireysel Learning Agreement."),"core_courses":["36 ECTS Core Courses (tutor-defined)","6 ECTS Multidisciplinary Courses","2 ECTS Science in Perspective","8 ECTS Semester Project","8 ECTS Industrial Internship (12 weeks)","30 ECTS Master's Thesis (max. six months full-time)"],"mandatory_courses":["Semester Project","Industrial Internship","Master's Thesis"],"thesis_type":"30 ECTS independent research thesis (maximum six months full-time)","mandatory_internship":True,"curriculum_url":curr,"verification_notes":bi("ETH explicitly describes the six-category 90-ECTS structure. Tutor-defined core choices mean the card does not invent a fixed specialisation track.","ETH alti kategorili 90 AKTS yapisini acikca tanimlar. Core dersler tutor tarafindan belirlendigi icin kart sabit uzmanlasma hatti uydurmaz.")})
 s=r.setdefault("source_profile",{});add(s,src(fee,"ETH tuition fee groups","official_tuition_page",["tuition"],"Official ETH table gives the fee-group rate; group classification is conditional.","Resmi ETH tablosu fee-group ucretini verir; grup siniflandirmasi kosulludur."));add(s,src(esop,"ETH Excellence Scholarship & Opportunity Programme","official_scholarship_page",["scholarship","funding","deadline"],"Official page gives current HS27 dates, amount, waiver and selection conditions.","Resmi sayfa guncel HS27 tarihini, tutari, muafiyeti ve secim kosullarini verir."));add(s,src(living,"ETH Financial Aid cost of living 2025","official_cost_of_living_page",["housing","living"],"Official Canton Zurich budget gives annual room-rent and individual-living-cost figures.","Resmi Kanton Zurich butcesi yillik oda kirasi ve bireysel yasam maliyeti verir."));add(s,src(curr,"ETH MSc Mechanical Engineering curriculum","official_curriculum_page",["curriculum"],"Official curriculum gives categories, ECTS, internship and thesis structure.","Resmi mufredat kategorileri, AKTS'leri, staj ve tez yapisini verir."));s.update({"official_tuition_page":fee,"official_scholarship_page":esop,"official_cost_of_living_page":living,"official_curriculum_page":curr,"last_verified":CHECKED});s.setdefault("field_confidence",{}).update({"tuition":"medium","scholarship":"high","living_profile":"high","housing":"high","curriculum":"high"});save(p,raw,d)

